          reject(new Error('Failed to parse response or assertion failed'));
        }
      });
    });

    req.on('error', (e) => {
      reject(e);
    });

    req.end();
  });
}

// Run the test
testOkEndpoint()
  .then(() => process.exit(0))
  .catch(err => {
    console.error('Test FAILED:', err.message);
    process.exit(1);
  });
